require_once __DIR__ . '/../includes/config.php';
require_role('admin');db_required();$rows=$pdo->query('SELECT e.*,u.name AS host_name FROM events e LEFT JOIN users u ON u.id=e.host_id ORDER BY e.event_date DESC')->fetchAll();$page_title='Manage Events';require __DIR__.'/../includes/header.php';?><div class="container py-5"><div class="d-flex justify-content-between align-items-end mb-4"><div><div class="section-kicker">Operations</div><h2 class="fw-bold">Published events</h2></div><a href="/admin/requests.php" class="btn btn-primary rounded-pill">Review proposals</a></div><div class="dash-card overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Event</th><th>Host</th><th>Date</th><th>Venue</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['title'])?></strong><div class="small text-secondary"><?=e($r['category'])?></div></td><td><?=e($r['host_name']??'—')?></td><td><?=date('d M Y · h:i A',strtotime($r['event_date']))?></td><td><?=e($r['venue'])?></td><td><?=status_badge($r['status'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="empty">No events published.</td></tr><?php endif;?></tbody></table></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
